//go:build linux

package main

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"

	"rosieos/offline-programming/v1/internal/denseexec"
	"rosieos/offline-programming/v1/internal/targets"
	"rosieos/rt-core/sdk/control"
	"rosieos/rt-core/simfixture"
)

// A J4 inertia program generated by tuningreport for the the 1430 cell simulation
// configuration goes through the production HTTP handler, picker, public
// adapter and native simulator: upload, the cell's checks, Load, Play to
// completion; a second run Stopped mid-sweep; the upload refused once the
// arm is off the start; a third run ended by the heartbeat deadman. Every
// wait is on observed native state; the bounds are the configuration's.
func TestTestProgramInertiaPlanComposed(t *testing.T) {
	if os.Getenv("RTCORE_COMPOSED") != "1" {
		t.Skip("set RTCORE_COMPOSED=1 after make control sim in rt-core")
	}
	root, err := filepath.Abs("../../rt-core")
	if err != nil {
		t.Fatal(err)
	}
	build, err := os.MkdirTemp(filepath.Join(root, "build"), "olp-testprog-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(build) })
	dir, err := os.MkdirTemp("", "tp-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	raw, err := os.ReadFile(filepath.Join(root, "config/machines/simulation/simulation-rosie1420.json"))
	if err != nil {
		t.Fatal(err)
	}
	var machine map[string]json.RawMessage
	if err := json.Unmarshal(raw, &machine); err != nil {
		t.Fatal(err)
	}
	// Unverified container scheduling allowance: 200000000 ns (the compiler
	// accepts up to 249999999). In Docker on
	// the Mac beside other agents' containers (load average 21-26,
	// 2026-10-09) the the 1430 cell simulation's 20 ms failed native Home on a
	// 20.6 ms gap and 50 ms faulted a run on cycle_deadline; every axis,
	// limit and Home rule stays as compiled.
	machine["max_cycle_lateness_ns"] = json.RawMessage("200000000")
	if raw, err = json.Marshal(machine); err != nil {
		t.Fatal(err)
	}
	machinePath := filepath.Join(build, "simulation-rosie1420.json")
	if err := os.WriteFile(machinePath, raw, 0o600); err != nil {
		t.Fatal(err)
	}
	compiled, args, err := simfixture.Compile(root, machinePath, filepath.Join(build, "config"))
	if err != nil {
		t.Fatal(err)
	}
	spawn := func(name string, args ...string) {
		t.Helper()
		log, err := os.Create(filepath.Join(build, name+".log"))
		if err != nil {
			t.Fatal(err)
		}
		cmd := exec.Command(filepath.Join(root, "build", name), args...)
		cmd.Dir, cmd.Stdout, cmd.Stderr = build, log, log
		if err := cmd.Start(); err != nil {
			log.Close()
			t.Fatal(err)
		}
		t.Cleanup(func() {
			_ = cmd.Process.Signal(syscall.SIGTERM)
			done := make(chan error, 1)
			go func() { done <- cmd.Wait() }()
			select {
			case err := <-done:
				if err != nil {
					t.Errorf("%s: %v", name, err)
				}
			case <-time.After(5000 * time.Millisecond):
				_ = cmd.Process.Kill()
				<-done
				t.Errorf("%s failed to terminate", name)
			}
			log.Close()
			if keep := os.Getenv("TESTPROG_LOGS"); keep != "" && t.Failed() {
				raw, _ := os.ReadFile(log.Name())
				_ = os.MkdirAll(keep, 0o755)
				_ = os.WriteFile(filepath.Join(keep, name+".log"), raw, 0o644)
			}
			if t.Failed() {
				raw, _ := os.ReadFile(log.Name())
				if len(raw) > 12000 {
					raw = raw[len(raw)-12000:]
				}
				t.Logf("%s: %s", name, raw)
			}
		})
	}
	// Unverified test watchdog: 240000 ms; only observed state satisfies waits.
	ctx, cancel := context.WithTimeout(context.Background(), 240000*time.Millisecond)
	defer cancel()
	var await func(what string, predicate func() bool)
	const axisMask = 0x3f
	waitFor := func(tt *testing.T, what string, predicate func() bool) {
		tt.Helper()
		ticker := time.NewTicker(10 * time.Millisecond)
		defer ticker.Stop()
		for !predicate() {
			select {
			case <-ctx.Done():
				tt.Fatalf("%s: not observed (%v)", what, ctx.Err())
			case <-ticker.C:
			}
		}
	}
	await = func(what string, predicate func() bool) { waitFor(t, what, predicate) }
	coreSocket, socket := filepath.Join(dir, "i.sock"), filepath.Join(dir, "c.sock")
	spawn("rosie-rt-core-sim", append(args, "--socket-path", coreSocket)...)
	await("configuration verified", func() bool {
		raw, _ := os.ReadFile(filepath.Join(dir, "metrics.json"))
		var m struct {
			ConfigVerifiedMask uint32 `json:"config_verified_mask"`
		}
		return json.Unmarshal(raw, &m) == nil && m.ConfigVerifiedMask&axisMask == axisMask
	})
	spawn("rt-control", "--core-socket", coreSocket, "--socket", socket, "--compiled-config", compiled, "--configuration-sha256", filepath.Base(compiled),
		"--backend", "simulation", "--pair-id", "bench", "--pair-revision", "7")
	c, err := control.Dial(control.UnixPath(socket))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { c.Close() })
	await("native status", func() bool { s, err := c.Status(ctx); return err == nil && s.Motion.TimeNS > 0 })
	d, err := c.Describe(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if d.Robot == nil || d.Robot.ModelID != "rosie_1420_v1" || len(d.Axes) != 6 {
		t.Fatalf("the simulator does not describe rosie_1420_v1's six axes: %+v", d.Robot)
	}

	store := denseexec.NewTestPrograms()
	p := targets.NewPicker(targets.PickerOptions{
		Catalogue: targets.CellCatalogue{Cells: []targets.Cell{{CellID: "sim", Models: []string{"rosie_1420_v1"}, RequestedMode: "simulation", Execution: targets.CellExecution{Local: true}}}},
		Local:     denseexec.RTCoreConfig{Socket: socket, Binding: control.Binding{PairID: "bench", Revision: 7}, AxisMask: axisMask},
		Source:    denseexec.Config{ControllerID: "offline-programming:test-program", TestPrograms: store},
	})
	t.Cleanup(func() { p.Close(context.Background()) })
	server := httptest.NewServer(NewServer(ServerOptions{DenseExecution: p, TestPrograms: store}).Handler())
	t.Cleanup(server.Close)
	// cur is the running (sub)test: the helpers fail it, never its parent.
	cur := t
	request := func(method, path string, body any, out any) (int, map[string]any) {
		cur.Helper()
		raw, err := json.Marshal(body)
		if err != nil {
			cur.Fatal(err)
		}
		req, err := http.NewRequestWithContext(ctx, method, server.URL+"/api/offline-programming/v1/"+path, bytes.NewReader(raw))
		if err != nil {
			cur.Fatal(err)
		}
		req.Header.Set("X-RT-Target-Generation", "1")
		req.Header.Set("X-RT-Target-Cell", "sim")
		req.Header.Set(clientIDHeader, "tab-testprogram")
		resp, err := server.Client().Do(req)
		if err != nil {
			cur.Fatal(err)
		}
		defer resp.Body.Close()
		payload, _ := readAll(resp)
		decoded := map[string]any{}
		_ = json.Unmarshal(payload, &decoded)
		if out != nil && resp.StatusCode == http.StatusOK {
			if err := json.Unmarshal(payload, out); err != nil {
				cur.Fatal(err)
			}
		}
		return resp.StatusCode, decoded
	}
	ok := func(method, path string, body any, out any) {
		cur.Helper()
		if code, payload := request(method, path, body, out); code != http.StatusOK {
			cur.Fatalf("%s %s: %d %v", method, path, code, payload)
		}
	}
	status := func() denseexec.StatusBody {
		cur.Helper()
		var s denseexec.StatusBody
		ok(http.MethodGet, "dense-execution/status", nil, &s)
		return s
	}
	observe := func() control.Status {
		cur.Helper()
		s, err := c.Status(ctx)
		if err != nil {
			cur.Fatal(err)
		}
		return s
	}
	// nativeState is what the operator would need to judge a failed run.
	nativeState := func() string {
		s := observe()
		axes := make([]string, 0, len(s.Axes))
		for i, a := range s.Axes {
			axes = append(axes, fmt.Sprintf("J%d %.4f deg %s/%s %s %s", i+1, a.LogicalPosition*180/math.Pi, a.Readiness, a.PositionState, a.PositionReason, a.DriveAlarm))
		}
		return fmt.Sprintf("execution %+v; core safety_fault_mask %d execution_fault_reasons %d home_valid %d; axes %s",
			s.Execution, s.Core.SafetyFaultMask, s.Core.ExecutionFaultReasons, s.Core.HomeValidMask, strings.Join(axes, "; "))
	}
	await = func(what string, predicate func() bool) { cur.Helper(); waitFor(cur, what, predicate) }
	// underWay waits until J4 is deg from q, failing with the state if the
	// session ends first or nothing moves within 30 s (the program reaches
	// 3 deg about 1.5 s after Play).
	underWay := func(q, deg float64) {
		cur.Helper()
		deadline := time.Now().Add(30 * time.Second)
		await(fmt.Sprintf("J4 %.0f deg under way", deg), func() bool {
			if math.Abs(observe().Axes[3].LogicalPosition-q) > deg*math.Pi/180 {
				return true
			}
			if s := status(); s.Session == nil || s.Session.State == "stopped" || s.Session.State == "done" || time.Now().After(deadline) {
				cur.Fatalf("J4 did not move: session %+v; %s", s.Session, nativeState())
			}
			return false
		})
	}
	run := func(name string, body func(t *testing.T)) bool {
		return t.Run(name, func(sub *testing.T) {
			cur = sub
			defer func() { cur = t }()
			body(sub)
		})
	}
	ok(http.MethodPost, "targets/select", targets.Selection{CellID: "sim", ModelID: "rosie_1420_v1"}, nil)

	// The browser's heartbeat: every second while the server holds a session,
	// from Connect on, as the Machine panel does (the deadman covers Home and
	// Arm too).
	var beat sync.Mutex
	beating := true
	heartbeatCtx, stopHeartbeat := context.WithCancel(ctx)
	heartbeatDone := make(chan struct{})
	go func() {
		defer close(heartbeatDone)
		ticker := time.NewTicker(1000 * time.Millisecond)
		defer ticker.Stop()
		for {
			select {
			case <-heartbeatCtx.Done():
				return
			case <-ticker.C:
			}
			beat.Lock()
			on := beating
			beat.Unlock()
			if s := p.Status(heartbeatCtx); on && s.Session != nil && s.Session.State != "stopped" {
				raw, _ := json.Marshal(map[string]string{"session_id": s.Session.ID})
				req, err := http.NewRequestWithContext(heartbeatCtx, http.MethodPost, server.URL+"/api/offline-programming/v1/dense-execution/heartbeat", bytes.NewReader(raw))
				if err != nil {
					continue
				}
				req.Header.Set(clientIDHeader, "tab-testprogram")
				if resp, err := server.Client().Do(req); err == nil {
					resp.Body.Close()
				}
			}
		}
	}()
	t.Cleanup(func() { stopHeartbeat(); <-heartbeatDone })

	if code, payload := request(http.MethodPost, "dense-execution/home", nil, nil); code != http.StatusOK {
		reason := ""
		if s := status(); s.RTCore != nil {
			reason = s.RTCore.Reason
		}
		t.Fatalf("Home: %d %v; OLP status reason %q", code, payload, reason)
	}
	await("Home on every axis", func() bool {
		s := observe()
		return s.Core.HomeValidMask&axisMask == axisMask && s.Core.CommissioningPhase == 0
	})

	// The program, generated by the tool from the held pose against the
	// configuration the simulator runs.
	start := observe()
	startDeg := make([]string, 6)
	for i := range startDeg {
		startDeg[i] = fmt.Sprintf("%.9f", start.Axes[i].LogicalPosition*180/math.Pi)
	}
	out := filepath.Join(build, "plan")
	generate := exec.CommandContext(ctx, "go", "run", "./tools/tuningreport")
	if bin := os.Getenv("TUNINGREPORT_BIN"); bin != "" {
		generate = exec.CommandContext(ctx, bin)
	}
	generate.Args = append(generate.Args, "inertia-plan", "--compiled", compiled, "--manifest-revision", "7", "--joint", "J4", "--accels", "200,400", "--repeats", "1",
		"--start-deg", strings.Join(startDeg, ","), "--out", out)
	generate.Dir = root
	if raw, err := generate.CombinedOutput(); err != nil {
		t.Fatalf("tuningreport inertia-plan: %v\n%s", err, raw)
	} else {
		t.Logf("tuningreport inertia-plan: %s", raw)
	}
	planJSON, err := os.ReadFile(filepath.Join(out, "plan.json"))
	if err != nil {
		t.Fatal(err)
	}
	var plan struct {
		Program   string     `json:"program_file"`
		DurationS float64    `json:"duration_s"`
		WindowDeg [2]float64 `json:"window_deg"`
	}
	if err := json.Unmarshal(planJSON, &plan); err != nil {
		t.Fatal(err)
	}
	rdt, err := os.ReadFile(filepath.Join(out, plan.Program))
	if err != nil {
		t.Fatal(err)
	}
	upload := map[string]any{"file_name": plan.Program, "program_base64": base64.StdEncoding.EncodeToString(rdt), "plan_json": json.RawMessage(planJSON), "plan_file_name": "plan.json"}
	var uploaded struct {
		Program denseexec.TestProgram `json:"program"`
		Checks  []string              `json:"checks"`
	}
	ok(http.MethodPost, "dense-execution/test-program", upload, &uploaded)
	program := uploaded.Program
	if program.Provenance == nil || program.Provenance.Joint != "J4" || len(uploaded.Checks) != 4 {
		t.Fatalf("upload: %+v %q", program, uploaded.Checks)
	}
	t.Logf("uploaded %s %s: %q", program.FileName, program.TrajectoryDigest, uploaded.Checks)

	tolerance := make([]float64, 6)
	for i := range tolerance {
		tolerance[i] = d.Axes[i].CompletionTolerance
	}
	load := func() string {
		cur.Helper()
		var loaded denseexec.LoadResult
		ok(http.MethodPost, "dense-execution/load", denseexec.LoadRequest{Identity: program.Identity, Source: denseexec.TestProgramSource}, &loaded)
		if s := loaded.Status.Session; s == nil || s.Source != denseexec.TestProgramSource || s.TestProgram == nil || s.TestProgram.FileName != plan.Program {
			cur.Fatalf("loaded session is not labelled a test program: %+v", s)
		}
		return loaded.SessionID
	}

	if !run("plays_to_completion", func(t *testing.T) {
		ok(http.MethodPost, "dense-execution/arm", map[string]bool{"armed": true}, nil)
		session := load()
		began := time.Now()
		ok(http.MethodPost, "dense-execution/play", map[string]string{"session_id": session}, nil)
		var j4Min, j4Max = math.Inf(1), math.Inf(-1)
		var otherWorst float64
		await("program completion", func() bool {
			s := observe()
			for i := 0; i < 6; i++ {
				q := s.Axes[i].LogicalPosition
				if i == 3 {
					j4Min, j4Max = math.Min(j4Min, q), math.Max(j4Max, q)
				} else {
					otherWorst = math.Max(otherWorst, math.Abs(q-start.Axes[i].LogicalPosition)/tolerance[i])
				}
			}
			body := status()
			if body.Session == nil || body.Session.State == "stopped" {
				t.Fatalf("session ended without completing: %+v; %s", body.Session, nativeState())
			}
			return body.Session.State == "done"
		})
		elapsed := time.Since(began).Seconds()
		final := observe()
		if final.Execution.State != "completed" || final.Execution.Identity.SourceDigest != program.TrajectoryDigest {
			t.Fatalf("native execution: %+v", final.Execution)
		}
		lowDeg, highDeg := j4Min*180/math.Pi, j4Max*180/math.Pi
		// The sweep covers the planned window (within the 1 deg the status
		// sampling can miss at the turnarounds), no other joint leaves its
		// completion tolerance, and the program ends where it began.
		if lowDeg > plan.WindowDeg[0]+1 || highDeg < plan.WindowDeg[1]-1 || lowDeg < plan.WindowDeg[0]-0.1 || highDeg > plan.WindowDeg[1]+0.1 {
			t.Fatalf("J4 swept %.3f..%.3f deg, planned %.3f..%.3f", lowDeg, highDeg, plan.WindowDeg[0], plan.WindowDeg[1])
		}
		if otherWorst > 1 {
			t.Fatalf("another joint moved %.2f x its completion tolerance", otherWorst)
		}
		if math.Abs(final.Axes[3].LogicalPosition-start.Axes[3].LogicalPosition) > tolerance[3] {
			t.Fatalf("J4 ended %.4f deg from its start", (final.Axes[3].LogicalPosition-start.Axes[3].LogicalPosition)*180/math.Pi)
		}
		if elapsed < plan.DurationS {
			t.Fatalf("completed in %.1f s, the program lasts %.1f s", elapsed, plan.DurationS)
		}
		t.Logf("completed in %.1f s (program %.1f s); J4 swept %.3f..%.3f deg; other joints within %.2f x tolerance", elapsed, plan.DurationS, lowDeg, highDeg, otherWorst)
	}) {
		return
	}

	if !run("stop_mid_run", func(t *testing.T) {
		session := load()
		ok(http.MethodPost, "dense-execution/play", map[string]string{"session_id": session}, nil)
		// Stop once J4 is 3 deg into its move to the window.
		underWay(start.Axes[3].LogicalPosition, 3)
		pressed := time.Now()
		var stopped denseexec.StopResult
		ok(http.MethodPost, "dense-execution/stop", nil, &stopped)
		if !stopped.Stopped {
			t.Fatalf("stop: %+v", stopped)
		}
		await("native disarm", func() bool {
			s := observe()
			return s.Core.Armed == 0 && s.Core.AxisEnableMask == 0 && s.Execution.State != "executing"
		})
		// Unverified inhibition ceiling: 3000 ms from request to native off,
		// the bound the Cartesian Stop test holds.
		if elapsed := time.Since(pressed); elapsed > 3000*time.Millisecond {
			t.Fatalf("native off %.0f ms after Stop", elapsed.Seconds()*1000)
		}
		body := status()
		if body.Session == nil || body.Session.State != "stopped" || body.Session.Lease.Held || c.Grant().Session != "" {
			t.Fatalf("after Stop: %+v", body.Session)
		}
		held := observe().Axes[3].LogicalPosition
		if math.Abs(held-start.Axes[3].LogicalPosition) < 3*math.Pi/180 || math.Abs(held-start.Axes[3].LogicalPosition) > math.Abs(plan.WindowDeg[0])*math.Pi/180+0.01 {
			t.Fatalf("J4 held %.3f deg: not mid-run", held*180/math.Pi)
		}
		t.Logf("stopped mid-run with J4 at %.3f deg, native off %.0f ms after the request", held*180/math.Pi, time.Since(pressed).Seconds()*1000)
	}) {
		return
	}

	if !run("refused_off_start", func(t *testing.T) {
		code, payload := request(http.MethodPost, "dense-execution/test-program", upload, nil)
		if code != http.StatusConflict || payload["error"] != "test_program_start_mismatch" || !strings.Contains(fmt.Sprint(payload["detail"]), "J4 is at") {
			t.Fatalf("upload off the start: %d %v", code, payload)
		}
		code, payload = request(http.MethodPost, "dense-execution/load", denseexec.LoadRequest{Identity: program.Identity, Source: denseexec.TestProgramSource}, nil)
		if code != http.StatusNotFound || payload["error"] != "test_program_not_found" {
			t.Fatalf("load of the refused upload: %d %v", code, payload)
		}
	}) {
		return
	}

	run("heartbeat_deadman", func(t *testing.T) {
		// Back to the start with an ordinary joint Move-to, then upload again.
		ok(http.MethodPost, "dense-execution/arm", map[string]bool{"armed": true}, nil)
		body := status()
		var jog denseexec.JointJogState
		ok(http.MethodGet, "dense-execution/jog/state", nil, &jog)
		target := start.Axes[3].LogicalPosition
		ok(http.MethodPost, "dense-execution/move", denseexec.JointMoveIntent{TargetID: "bench", SessionID: body.Session.ID, Revision: jog.Revision, Axis: 3,
			Fraction: 0.2, Axes: []denseexec.JointMoveAxis{{Axis: 3, PositionRad: &target}}}, nil)
		await("J4 back at the start", func() bool {
			var state denseexec.JointJogState
			ok(http.MethodGet, "dense-execution/jog/state", nil, &state)
			return state.Move.State == "done" && math.Abs(observe().Axes[3].LogicalPosition-target) <= tolerance[3]
		})
		ok(http.MethodPost, "dense-execution/test-program", upload, nil)
		session := load()
		ok(http.MethodPost, "dense-execution/play", map[string]string{"session_id": session}, nil)
		underWay(target, 1)
		beat.Lock()
		beating = false
		beat.Unlock()
		silent := time.Now()
		await("deadman stop", func() bool {
			s := status()
			return s.Session != nil && s.Session.State == "stopped"
		})
		after := time.Since(silent)
		await("native disarm", func() bool { s := observe(); return s.Core.Armed == 0 && s.Execution.State != "executing" })
		s := status()
		if !strings.Contains(s.Session.StopReason+s.Session.LastError+fmt.Sprint(s.RTCore.Reason), "ui_heartbeat_lost") {
			t.Fatalf("stopped without the heartbeat reason: session %+v reason %q", s.Session, s.RTCore.Reason)
		}
		// The deadline is the server's (DefaultHeartbeatDeadline, 5000 ms) after
		// the last beat, which was at most one beat period before silence.
		if after < denseexec.DefaultHeartbeatDeadline-1000*time.Millisecond || after > denseexec.DefaultHeartbeatDeadline+2000*time.Millisecond {
			t.Fatalf("deadman after %.1f s of silence", after.Seconds())
		}
		t.Logf("heartbeat deadman stopped the test program %.1f s after the last beat could have landed", after.Seconds())
	})
}

func readAll(resp *http.Response) ([]byte, error) {
	var buf bytes.Buffer
	_, err := buf.ReadFrom(resp.Body)
	return buf.Bytes(), err
}
